  const chartRequest=siteApi('metrics').then(data=>({data}),error=>({error}));
  const d=await overviewRequest,running=d.entries.filter(x=>['seated','sitting_out','draining'].includes(x.status)).reduce((s,x)=>s+x.count,0);
  const trend=card('Scheduled vs actually running','<div id="entry-trend-panel"><p class="sub">Loading activity chart?</p></div>');
  const machineHealth=d.machine_summary.warnings.length?`<div class="health-warnings">${d.machine_summary.warnings.map(w=>`<p>${pill('Warning','orange')} <strong>${esc(w.machine)}</strong> — ${esc(w.message)}</p>`).join('')}</div>`:`<div class="notice health-ok">No sustained CPU, memory or disk warnings.</div>`;
  if(!render(gen,`Your ${esc(state.site.name)} operation at a glance.`,stats([['Bot entries',`${running} / ${d.scheduled_target}`,'Confirmed seated / scheduled now'],['Accounts',d.accounts,`${d.synthetic_accounts} simulation-only accounts`],['Machines',`${d.machine_summary.online} / ${d.machines.length}`,`${d.machine_summary.online} online · ${d.machine_summary.offline} offline`],['Hand histories',d.hand_histories.today||0,`${d.hand_histories.last_30_days||0} during the last 30 days`]])+trend+`<div class="grid-2">${card('System health',`<div class="card-body"><h3>${d.machine_summary.online} machines online · ${d.machine_summary.offline} offline</h3>${machineHealth}<a class="button" href="#machines">View machines →</a></div>`)}${card('Weekly operation',`<div class="card-body"><p>${pill(d.schedule.enabled?'Enabled':'Scheduling paused',d.schedule.enabled?'green':'orange')}</p><h3>${d.schedule.windows.length} recurring windows</h3><p>Timezone: ${esc(d.schedule.timezone)}</p><a class="button" href="#schedule">Edit schedule →</a></div>`)}</div>`))return;
  let refreshingEntries=false;clearInterval(state.poll);state.poll=setInterval(async()=>{if(refreshingEntries||gen!==state.generation)return;refreshingEntries=true;try{const latest=await siteApi('overview');if(gen===state.generation){const confirmed=latest.entries.filter(e=>['seated','sitting_out','draining'].includes(e.status)).reduce((n,e)=>n+e.count,0);const card=$('#workspace .stats .stat');if(card){$('.stat-value',card).textContent=`${confirmed} / ${latest.scheduled_target}`;const pending=latest.entries.filter(e=>!['seated','sitting_out','draining'].includes(e.status)).reduce((n,e)=>n+e.count,0);$('.stat-note',card).textContent='Confirmed seated / scheduled now'+(pending?` ? ${pending} pending or unconfirmed`:'');}}}catch{}finally{refreshingEntries=false;}},15000);
  const loadChart=async request=>{
    const result=await request;if(gen!==state.generation)return;
    const holder=$('#entry-trend-panel');
    if(result.error){holder.innerHTML=`<div class="notice">The activity chart could not be loaded. Your summary is still available.</div><button class="button" id="entry-chart-retry">Retry chart</button>`;$('#entry-chart-retry').onclick=()=>{holder.innerHTML='<p class="sub">Loading activity chart?</p>';loadChart(siteApi('metrics').then(data=>({data}),error=>({error})));};return;}
    const metrics=result.data;
    holder.innerHTML=`<form id="entry-chart-filter" class="entry-chart-filter">${field('From','from',metrics.from,'date','required')}${field('To','to',metrics.to,'date','required')}<button class="button primary">Apply dates</button></form><div id="entry-chart">${entryTrendChart(metrics)}</div>`;
    attachEntryTrendChart($('#entry-chart'),metrics);
    $('#entry-chart-filter').onsubmit=async e=>{e.preventDefault();const b=$('button',e.target),v=formData(e.target);b.disabled=true;b.textContent='Loading?';try{const result=await siteApi('metrics?'+new URLSearchParams(v));if(gen===state.generation)attachEntryTrendChart($('#entry-chart'),result);}catch(err){toast(err.message);}finally{b.disabled=false;b.textContent='Apply dates';}};
  };
  await loadChart(chartRequest);
