pages.schedule=async gen=>{
 const d=await siteApi('schedule');let windows=structuredClone(d.windows),version=d.version;
 if(!render(gen,'Recurring targets in your site’s local timezone. Every add, edit and removal saves immediately.',`<div class="notice">${d.enabled?'Scheduling is enabled.':'Scheduling is paused.'} Timezone: ${esc(d.timezone)} · Changes auto-save.</div>`+card('Weekly targets','<div class="card-body" id="week"></div>')+card('Schedule windows','<div id="windows"></div>'),`<span class="edit-action">${button('+ Add window','add-window',true)}</span>`))return;
 const persist=async(next,message)=>{const result=await siteApi('schedule','PUT',{windows:next,timezone:d.timezone,version});windows=next;version=result.version;draw();toast(message);};
 const timeInput=(name,value,start=false)=>`<input class="schedule-time" name="${name}" value="${value}" inputmode="numeric" placeholder="HH:MM" pattern="${start?'(?:[01][0-9]|2[0-3]):[0-5][0-9]':'(?:(?:[01][0-9]|2[0-3]):[0-5][0-9]|24:00)'}" required>`;
 const draw=()=>{
  $('#week').innerHTML=weeklyTargetChart(windows,days,d.timezone);
  $('#windows').innerHTML=windows.length?table(['Day','From','To','Entries',''],windows.map((w,i)=>`<tr data-window-row="${i}"><td><select data-window-field="weekday">${days.map((day,index)=>`<option value="${index}" ${index===w.weekday?'selected':''}>${day}</option>`).join('')}</select></td><td>${timeInput('start',clock(w.start_minute),true).replace('<input','<input data-window-field="start"')}</td><td>${timeInput('end',clock(w.end_minute)).replace('<input','<input data-window-field="end"')}</td><td><input class="schedule-target" data-window-field="target" type="number" min="0" value="${w.target}" required></td><td><button class="button small danger edit-action" data-remove="${i}">Remove</button></td></tr>`)):empty('No schedule windows','Add a window to define when entries should play.');
  document.querySelectorAll('[data-window-field]').forEach(input=>input.onchange=async()=>{const row=input.closest('[data-window-row]'),index=+row.dataset.windowRow,next=structuredClone(windows),fieldName=input.dataset.windowField;try{if(fieldName==='weekday'||fieldName==='target')next[index][fieldName]=+input.value;else next[index][fieldName+'_minute']=minutes(input.value);await persist(next,'Schedule window updated');}catch(error){toast(error.message);draw();}});
  document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{try{await persist(windows.filter((_,i)=>i!==+b.dataset.remove),'Schedule window removed');}catch(error){toast(error.message);}});
  bindWeeklyTargetChart($('#week'),windows,days,index=>document.querySelector(`[data-window-row="${index}"] [data-window-field="target"]`)?.focus());
 };
 draw();
 $('#add-window').onclick=()=>{
  const dialog=$('#dialog'),todayName=new Intl.DateTimeFormat('en-US',{weekday:'long',timeZone:d.timezone}).format(new Date()),today=Math.max(0,days.indexOf(todayName));
  const dayPicker=`<div class="field span-all"><span>Days</span><div class="day-preset-actions"><button type="button" class="button small" data-day-set="all">Every day</button><button type="button" class="button small" data-day-set="weekdays">Weekdays</button><button type="button" class="button small" data-day-set="weekend">Weekend</button><button type="button" class="button small ghost" data-day-set="clear">Clear</button></div><div class="schedule-day-picker">${days.map((day,index)=>`<label><input type="checkbox" name="weekdays" value="${index}" ${index===today?'checked':''}><span>${day.slice(0,3)}</span></label>`).join('')}</div></div>`;
  dialog.innerHTML=`<form><div class="dialog-head"><div><h2>Add schedule windows</h2><p>Select one or several days. Each submission saves immediately and this window stays open.</p></div><button type="button" class="icon-button" id="close-dialog">×</button></div><div class="dialog-content"><div class="form-grid">${dayPicker}<div class="schedule-time-row span-all"><label class="field"><span>Start (24-hour)</span>${timeInput('start','17:00',true)}</label><label class="field"><span>End (24-hour)</span>${timeInput('end','18:00')}</label></div><div class="schedule-total-row span-all">${field('Total entries','target',56,'number','min="0" required')}</div></div><p class="dialog-error" role="alert"></p></div><div class="dialog-footer"><button type="button" class="button" id="cancel-dialog">Done</button><button class="button primary">Add and save</button></div></form>`;
  $('#close-dialog').onclick=$('#cancel-dialog').onclick=()=>dialog.close();
  document.querySelectorAll('[data-day-set]',dialog).forEach(control=>control.onclick=()=>{const set=control.dataset.daySet;document.querySelectorAll('[name="weekdays"]',dialog).forEach(box=>box.checked=set==='all'||set==='weekdays'&&+box.value<5||set==='weekend'&&+box.value>=5);});
  $('form',dialog).onsubmit=async event=>{event.preventDefault();const submit=$('button.primary',dialog),data=new FormData(event.target),values=Object.fromEntries(data),selected=data.getAll('weekdays').map(Number);submit.disabled=true;$('.dialog-error',dialog).textContent='';try{if(!selected.length)throw Error('Select at least one day');const additions=selected.map(weekday=>({weekday,start_minute:minutes(values.start),end_minute:minutes(values.end),target:+values.target})),next=[...windows,...additions];await persist(next,`${selected.length} schedule window${selected.length===1?'':'s'} added`);}catch(error){$('.dialog-error',dialog).textContent=error.message;}finally{submit.disabled=false;}};
  dialog.showModal();
 };
};
