 await Promise.allSettled(d.items.map(async m=>{try{const metrics=await siteApi(`machines/${m.id}/metrics?hours=24`);if(gen!==state.generation)return;const slot=$(`#machine-chart-${m.id}`);if(slot)slot.innerHTML=machineMetricChart(metrics);}catch(error){const slot=$(`#machine-chart-${m.id}`);if(slot)slot.innerHTML=`<div class="machine-chart-empty">Could not load performance history.</div>`;}}));
