  const body=`<div class="toolbar history-actions"><label class="checkbox-line"><input type="checkbox" id="select-page"> Select page</label><span>${button('Download selected','download-hh')}${button('Download all filtered','download-all-hh')}${button('Bot winnings','report-hh')}</span></div>${result.items.length?table(['','Hand','Hero','Game','BB','Humans','Hero winnings','Uploaded',''],rows):empty('No hands match','Try a wider date, bot, game or blind range.')}<div class="pagination"><button class="button small" id="hh-prev" ${page<=1?'disabled':''}>← Previous</button><span>Page ${page} of ${pages} · ${result.total} hands</span><button class="button small" id="hh-next" ${page>=pages?'disabled':''}>Next →</button></div>`;
